select id, customer_id, account_type, opened_date, avg(balance) over (partition by account_type) as account_type_avg_balance, lag(balance, 1) over (partition by account_type order by balance, id) as prev_balance, first_value(status, true) over (partition by customer_id order by opened_date, id rows between unbounded preceding and current row) as first_known_status, dense_rank() over (partition by customer_id, status order by balance desc nulls last) as balance_dense_rank from accounts
